        <div class="avatar-circle avatar-sm flex-shrink-0"
             :style="{ background: avatarBg(log.reporter?.name), color: avatarColor(log.reporter?.name) }">
          {{ log.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:13px;">{{ log.reporter?.name }}</strong>
            <small class="text-muted">{{ formatDate(log.created_at) }}</small>
          </div>
          <p style="font-size:13px;margin:0;">{{ log.description }}</p>
        </div>
      </div>

      <!-- replies (level 2), flattened, indented -->
      <div v-for="reply in log.replies || []" :key="reply.id" class="d-flex gap-2 align-items-start ms-4">
        <div class="avatar-circle avatar-xs flex-shrink-0"
             :style="{ background: avatarBg(reply.reporter?.name), color: avatarColor(reply.reporter?.name) }">
          {{ reply.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:12px;">{{ reply.reporter?.name }}</strong>
            <small class="text-muted" style="font-size:11px;">{{ formatDate(reply.created_at) }}</small>
          </div>
          <p style="font-size:12px;margin:0;">{{ reply.description }}</p>
        </div>
      </div>

      <!-- nested replies (level 3), flattened further -->
      <div v-for="reply in log.replies || []" :key="'n-' + reply.id">
        <div v-for="nested in reply.replies || []" :key="nested.id" class="d-flex gap-2 align-items-start ms-5">
          <div class="avatar-circle avatar-xs flex-shrink-0"
               :style="{ background: avatarBg(nested.reporter?.name), color: avatarColor(nested.reporter?.name) }">
