              <strong style="font-size:11px;">{{ nested.reporter?.name }}</strong>
              <small class="text-muted" style="font-size:10px;">{{ formatDate(nested.created_at) }}</small>
            </div>
            <p style="font-size:11px;margin:0;">{{ nested.description }}</p>
          </div>
        </div>
      </div>
    </template>
