      @change="handleFileUpload"
      accept="application/pdf"
      required
    >
    <input type="date" v-model="receipt_date" class="form-control w-25">
    <input type="number" step="any" v-model="receipt_amount" class="form-control w-25" placeholder="Enter Amount" required>

    <button class="btn btn-primary" type="submit"  :disabled="spinner">
      <span v-if="spinner" v-html="loadingSpinner()"></span>
      <span v-else>Submit</span>
    </button>
  </form>
</div>

