 v-if="((user_role_id == awaiter.role_id && awaits !=='no one')) || (user_permissions.includes('is_md') && item.status?.name !== 'paid') || (user_role_id == item.last_checker_id &&  item.status?.name !== 'paid')">    
    <div class="btn-group" >
            <button class="btn btn-secondary me-2"
