    Check
</button>

<button class="btn btn-danger me-2" 
    @click="approval_status = 4" 
    :disabled="isDisabled">
    Reject
</button>

<button class="btn btn-info me-2" 
    @click="approval_status = 14" 
    :disabled="isDisabled">
    Remark
</button>

<button class="btn btn-warning me-2" 
    @click="approval_status = 17" 
    :disabled="isDisabled">
    On Hold
</button>

          </div>
            </div>

      <div v-if="approval_status" class="mb-2 text-center">
        <span
