const approval_description = ref('')
const approval = ref('')

const approvalTotalCost = computed(() => {
  if (!item.value?.items) return 0
  return Math.floor( item.value.items.reduce(
    (sum, i) => sum + ((Number(i?.quantity) || 0) * (Number(i?.rate) || 0)), 0
  ))
})

const getApprovalChain = (row) => {
  getApprovalTransactions(row.id)
  approval.value = row
  requisitionItems.value = row.items.map((item, index) => ({
    ...item,
    order_item_id :  item?.requisition_items?.id,
    Sno: index + 1,
    item: item?.requisition_items?.remark,
    description: item?.requisition_items?.description + (item.description ? ' ( ' + item.description + ' )' : ''),
    rate: Number(item?.rate).toLocaleString() + '/=',
    total: (item?.quantity * item?.rate).toLocaleString() + '/=',
    selected:false,
    rate_original : item?.rate,
    requesting_quantity : '',
    request_description : ''
  }));

  awaits.value = row.awaits
  approval_description.value = row.approval_description;
  approvalChain.value = (row.roles_sequence || []).slice();
  lastApprovalRole.value = (row.roles_sequence?.length > 0)
  ? row.roles_sequence[row.roles_sequence.length - 1].role_id
  : null;
  awaiter.value = row.awaiting_approval || {};
  awaiter_id.value = row.awaiting_approval?.role_id || null;
  item_id.value = row.id;
  item_date.value = row.date;
  requisition_source_item_id.value = row;
  item.value = row;
  localChecked.value = false;
  last_checked_role_id.value = row.last_checked_in?.role_id
  convertCountDown(row.created_at);
  getLogs(row.id);

};


const remark = ref('')
const approveRequest = async () => {
  if(approval_status.value == 404){

    const payload =  {
      type: 'MESSAGE',
      reporter_id: user_id,
      source: 'LPO',        
      source_id: item_id.value,
      module: 'LPO & VOUCHERS',
      description: remark.value,
      status_id: 1
    }

        await axiosInstance.post('logs',payload)
        remark.value = '',
        approval_status.value = ''
          showMessage('Message Sent successfully');
  }else{
  const payload = {
    subcontractor_agreement_id : item.value.subcontractor_agreement_id,
    approval_group_id : route.params.group_id,
    status_id : approval_status.value,
    approval_item_id: item_id.value,
    role_id: user_role_id.value,
    remark: remark.value,
    remarker_id : JSON.parse(localStorage.getItem('user')).id,
    last_role: lastApprovalRole.value,
    requisition_type: requisition_source_item_id.value.requisition_type,
    project : requisition_source_item_id.value,
    requisition_items : requisition_source_item_id.value.items.map((item)=>({
      source_id: item.requisition_items.item_id,
      cost : item.requisition_items.quantity * item.requisition_items.rate,
      description : item.requisition_items.description,
      remark : "From LPO NO : " + item_id.value + " created on date " + item_date.value,
      remarker_id : JSON.parse(localStorage.getItem('user')).id,
      remarker : JSON.parse(localStorage.getItem('user')).name
    })),

    approval_items : requisitionItems.value.map(item => ({
      id : item.id,
      quantity: Number(item.quantity),
      rate: Number(item.rate_original)
    }))
  };


  await axiosInstance.post('approval-chains', payload);
  awaiter_id.value = '';
  remark.value = '',
  approval_status.value = ''
  document.getElementById('close-approval-modal').click()
  getApprovalItems();
  showMessage('data saved successfully');
  }
};

const sendNotification = inject('sendNotification')

const cancellation_request = ref(false)
const sending = ref(false)
const requestCancellation = async(item) =>{
  sending.value = true
  const payload = {
    requisition_id : approval.value.requisition,
    order_id : approval.value.approval_id,
    approval_group_id : approval.value.approval_group_id,
    requester_id : JSON.parse(localStorage.getItem('user')).id,
    description : 'Order Cancellation Request, '+newMessage.value
  }
  const message = JSON.parse(localStorage.getItem('user')).name + ' requested order ' + approval.value.approval_id + ' cancellation'
  try{
    await axiosInstance.post(`order-cancellations`,payload);
    showMessage('Request Sent!')
    // sendNotification('Order Cancellation !',message ,'',[8,39,54,34,32])
    sendNotification('Order Cancellation !',message ,[8,39,24])
    getLogs(approval.value.approval_id)
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    sending.value = false
  }


}


