// countdown for approval expiry (24 hours from created_at)
// countdown for approval expiry (24 hours from created_at)
const hours = ref(0);
const minutes = ref(0);
const seconds = ref(0);
const expired = ref(false);
let countdownTimer = null;

const convertCountDown = (createdDate) => {
  if (countdownTimer) clearInterval(countdownTimer);
  expired.value = false;

  const created = new Date(createdDate).getTime();
  const expiry = created + 24 * 60 * 60 * 1000; // 24 hours after creation

  const tick = () => {
    const remaining = Math.floor((expiry - Date.now()) / 1000);

    if (remaining <= 0) {
      expired.value = true;
      hours.value = 0;
      minutes.value = 0;
      seconds.value = 0;
      clearInterval(countdownTimer);
      return;
    }

    hours.value = Math.floor(remaining / 3600);
    minutes.value = Math.floor((remaining % 3600) / 60);
    seconds.value = remaining % 60;
  };

  tick();
  countdownTimer = setInterval(tick, 1000);
};

