    ];

    // ── Style: bold company title (row 0) ────────────────────────────
    if (ws['A1']) ws['A1'].s = { font: { bold: true, sz: 14 } };

    // ── Style: bold group label (row 7) ─────────────────────────────
    if (ws['A7']) ws['A7'].s = { font: { bold: true, sz: 12 } };

    // ── Style: bold column headers ───────────────────────────────────
    const headerRowIndex = headerRows.length; // 0-based row of columns row
    columns.forEach((_, colIndex) => {
      const cellAddress = XLSX.utils.encode_cell({ r: headerRowIndex, c: colIndex });
      if (ws[cellAddress]) {
        ws[cellAddress].s = {
          font: { bold: true },
          fill: { fgColor: { rgb: 'D3D3D3' } },
          alignment: { horizontal: 'center' },
        };
      }
    });

    // ── Style: bold total row ────────────────────────────────────────
    const totalRowIndex = headerRows.length + 1 + dataRows.length;
    columns.forEach((_, colIndex) => {
      const cellAddress = XLSX.utils.encode_cell({ r: totalRowIndex, c: colIndex });
      if (ws[cellAddress]) {
        ws[cellAddress].s = { font: { bold: true } };
      }
    });

    // ── Create workbook & download ───────────────────────────────────
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Report');

    const dateStr = new Date().toISOString().slice(0, 10);
    const fileName = `${groupLabel.replace(/ /g, '_')}_${dateStr}.xlsx`;

    XLSX.writeFile(wb, fileName);
    showMessage('Excel file downloaded successfully');

  } catch (error) {
    showError(`Failed to export: ${error.message}`);
  }
};

